using System.Text;

namespace Bork2d.Bake.Hosting;

/// <summary>
/// Writes the deterministic <c>BakeManifest.g.cs</c> source of the generated bake host.
/// </summary>
/// <remarks>
/// The generated file contains only the type manifest, the <c>Bind</c> and <c>AddToPack</c>
/// switches, and the host-load shape validation. Binding itself lives in the shared generic
/// <c>TomlShapeBinder</c> (Q-07), so no member-level code or reflection is generated. Output uses
/// <c>\n</c> line endings, no timestamps, and distinct types in source discovery order, so identical
/// inputs produce identical text (D-M4-13).
/// </remarks>
internal static class GeneratedBakeManifestWriter
{
    /// <summary>Gets the generated manifest file name.</summary>
    internal const string FileName = "BakeManifest.g.cs";

    /// <summary>Writes the manifest source for the mapped types.</summary>
    /// <param name="mappings">The validated distinct mappings in discovery order.</param>
    /// <returns>The generated C# source.</returns>
    internal static string Write(IReadOnlyList<BakeMappedType> mappings)
    {
        ArgumentNullException.ThrowIfNull(mappings);

        BakeMappedType[] distinct = [.. mappings
            .GroupBy(mapping => mapping.TypeName, StringComparer.Ordinal)
            .Select(group => group.First())];

        var lines = new List<string>
        {
            "// <auto-generated/>",
            "// Generated by 'bork2d-bake generate-host'. Do not edit; regenerate from the",
            "// project descriptor and Project.Common.",
            "#nullable enable",
            string.Empty,
            "[assembly: global::Bork2d.Bake.Hosting.BakeManifest(",
            "    typeof(global::Bork2d.BakeHost.BakeManifest))]",
            string.Empty,
            "namespace Bork2d.BakeHost;",
            string.Empty,
            "internal sealed class BakeManifest : global::Bork2d.Bake.Hosting.IBakeManifest",
            "{",
            "    private static readonly "
                + "global::Bork2d.Bake.Hosting.BakeTypeRegistration[] _types =",
        };

        if (mappings.Count == 0)
        {
            lines.Add("    [];");
        }
        else
        {
            lines.Add("    [");
            foreach (BakeMappedType mapping in mappings)
            {
                lines.Add(
                    "        new global::Bork2d.Bake.Hosting.BakeTypeRegistration("
                        + $"{Literal(mapping.TypeName)}, "
                        + "global::Bork2d.Bake.Hosting.BakeAssetKind.MessagePack),");
            }

            lines.Add("    ];");
        }

        lines.Add(string.Empty);
        lines.Add(
            "    public global::System.Collections.Generic.IReadOnlyList<"
                + "global::Bork2d.Bake.Hosting.BakeTypeRegistration> Types => _types;");
        lines.Add(string.Empty);
        lines.Add(
            "    public object? Bind(string typeName, "
                + "global::Bork2d.Bake.Toml.BakeBindContext context)");
        lines.Add("    {");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(typeName);");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(context);");
        lines.Add(string.Empty);

        if (distinct.Length == 0)
        {
            lines.Add("        throw new global::Bork2d.Bake.Toml.BakeBindException(");
            lines.Add("            \"The bake host has no mapped types to bind.\");");
        }
        else
        {
            lines.Add("        return typeName switch");
            lines.Add("        {");
            foreach (BakeMappedType mapping in distinct)
            {
                lines.Add(
                    $"            {Literal(mapping.TypeName)} => "
                        + "global::Bork2d.Bake.Toml.TomlShapeBinder.Bind<"
                        + $"{mapping.CSharpName}>(context),");
            }

            lines.Add("            _ => throw new global::Bork2d.Bake.Toml.BakeBindException(");
            lines.Add(
                "                \"The bake host has no binding for the mapped type '\" + "
                    + "typeName + \"'.\"),");
            lines.Add("        };");
        }

        lines.Add("    }");
        lines.Add(string.Empty);
        lines.Add("    public void AddToPack(");
        lines.Add("        global::Bork2d.Assets.Pack.PackBuilder builder,");
        lines.Add("        string typeName,");
        lines.Add("        string assetPath,");
        lines.Add("        object value)");
        lines.Add("    {");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(builder);");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(typeName);");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(assetPath);");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(value);");
        lines.Add(string.Empty);

        if (distinct.Length == 0)
        {
            lines.Add("        throw new global::Bork2d.Bake.Toml.BakeBindException(");
            lines.Add("            \"The bake host has no mapped types to pack.\");");
        }
        else
        {
            lines.Add("        switch (typeName)");
            lines.Add("        {");
            foreach (BakeMappedType mapping in distinct)
            {
                lines.Add($"            case {Literal(mapping.TypeName)}:");
                lines.Add(
                    "                builder.AddMessagePack<"
                        + $"{mapping.CSharpName}>(assetPath, ({mapping.CSharpName})value);");
                lines.Add("                break;");
            }

            lines.Add("            default:");
            lines.Add("                throw new global::Bork2d.Bake.Toml.BakeBindException(");
            lines.Add(
                "                    \"The bake host has no pack writer for the mapped type '\" + "
                    + "typeName + \"'.\");");
            lines.Add("        }");
        }

        lines.Add("    }");
        lines.Add(string.Empty);
        lines.Add(
            "    public void ValidateShapes("
                + "global::Bork2d.Bake.Diagnostics.BakeDiagnostics diagnostics)");
        lines.Add("    {");
        lines.Add("        global::System.ArgumentNullException.ThrowIfNull(diagnostics);");

        if (distinct.Length > 0)
        {
            lines.Add(string.Empty);
            foreach (BakeMappedType mapping in distinct)
            {
                lines.Add(
                    "        global::Bork2d.Bake.Hosting.BakeShapeValidator.ValidateRoot<"
                        + $"{mapping.CSharpName}>("
                        + $"{Literal(mapping.TypeName)}, "
                        + "diagnostics);");
            }
        }

        lines.Add("    }");
        lines.Add("}");

        var builder = new StringBuilder();
        foreach (string line in lines)
        {
            builder.Append(line).Append('\n');
        }

        return builder.ToString();
    }

    private static string Literal(string value)
    {
        var builder = new StringBuilder(value.Length + 2);
        builder.Append('"');
        foreach (char character in value)
        {
            switch (character)
            {
                case '\\':
                    builder.Append("\\\\");
                    break;
                case '"':
                    builder.Append("\\\"");
                    break;
                case '\n':
                    builder.Append("\\n");
                    break;
                case '\r':
                    builder.Append("\\r");
                    break;
                case '\t':
                    builder.Append("\\t");
                    break;
                default:
                    builder.Append(character);
                    break;
            }
        }

        builder.Append('"');
        return builder.ToString();
    }
}
